// lib
using MessagePack;

namespace Lib
{
    // Two int-keyed properties share key 0.
    // The second one reaches intMembers.Add(member.IntKey, ...) with the key already present.
    // On the collector pass that runs with reportDiagnostic == null (the source generator),
    // old throws ArgumentException ("An item with the same key has already been added"),
    // so the build shows a generator crash warning (CS8785) and no formatter is generated.
    // New skips the Add, so the build shows only the regular duplicate-key diagnostic.
    [MessagePackObject]
    public class DuplicateKeys
    {
        [Key(0)]
        public int First { get; set; }

        [Key(0)]
        public int Second { get; set; }
    }

    // Same shape with SuppressSourceGeneration = true (requirement 2234).
    [MessagePackObject(SuppressSourceGeneration = true)]
    public class DuplicateKeysSuppressed
    {
        [Key(0)]
        public int First { get; set; }

        [Key(0)]
        public int Second { get; set; }
    }
}

// app
using System;
using Lib;
using MessagePack;

public static class Program
{
    public static void Main()
    {
        var value = new DuplicateKeys { First = 1, Second = 2 };
        byte[] bytes = MessagePackSerializer.Serialize(value);
        Console.WriteLine(bytes.Length);

        var suppressed = new DuplicateKeysSuppressed { First = 3, Second = 4 };
        Console.WriteLine(suppressed.First + suppressed.Second);
    }
}
